using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTools
{
    [McpServerTool, Description("Fetches data from an external API endpoint and returns the JSON response.")]
    public static async Task<string> FetchApiData(
        IHttpClientFactory httpClientFactory,
        ILogger<IMcpServer> logger,
        [Description("The API path to request (e.g. \"/users/1\")")] string path,
        CancellationToken cancellationToken)
    {
        logger.LogInformation("Fetching API data from {Path}", path);

        using var client = httpClientFactory.CreateClient("ExternalApi");
        using var response = await client.GetAsync(path, cancellationToken);

        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        logger.LogInformation("Received {Length} chars from {Path}", json.Length, path);

        return json;
    }
}

